  uint32_t tmp;

  /* Check the parameters */
  assert_param(IS_PWR_BKP(BackupRegister));

  tmp = (uint32_t) &(PWR->BKP0R);
  tmp += (BackupRegister * 4U);

  /* Write the specified register */
  *(__IO uint32_t *)tmp = (uint16_t)Data;
}


